arduino.loop:
const float BETA_${COMP_SUFFIX} = 3950;
int analogValue_${COMP_SUFFIX} = analogRead(${OUT});
float celsius_${COMP_SUFFIX} = 1 / (log(1 / (1023. / analogValue_${COMP_SUFFIX} - 1)) / BETA_${COMP_SUFFIX} + 1.0 / 298.15) - 273.15;
Serial.print("Temperature: ");
Serial.print(celsius_${COMP_SUFFIX});
Serial.println(" ℃");
delay(500);
